def predict(board, action):
    mouse_row, mouse_col = action[1], action[2]
    action_char = action[0]

    row_start, row_end = max(0, mouse_row-1), min(63, mouse_row+1)
    col_start, col_end = max(0, mouse_col-1), min(64, mouse_col+1)

    affected_cells = [(r, c) for r in range(row_start, row_end) for c in range(col_start, col_end) if (r, c) != (mouse_row, mouse_col)]

    new_board = [row[:] for row in board]  # Create a copy of the board

    for r, c in affected_cells:
        if new_board[r][c] == 'c':
            new_board[r][c] = 'b'
        elif new_board[r][c] == 'b':
            new_board[r][c] = 'c'
        elif new_board[r][c] == 'W':
            new_board[r][c] = 'G'

    if action_char == 'MOUSE':
        if new_board[mouse_row][mouse_col] == 'c':
            new_board[mouse_row][mouse_col] = 'b'
        elif new_board[mouse_row][mouse_col] == 'b':
            new_board[mouse_row][mouse_col] = 'c'
        elif new_board[mouse_row][mouse_col] == 'W':
            new_board[mouse_row][mouse_col] = 'G'

    return [''.join(row) for row in new_board]
